Here's a simple arena allocator implementation in C using only the standard library:

```c
#include <stddef.h>
#include <stdlib.h>
#include <stdint.h>

#define ARENA_ALIGNMENT 16

typedef struct Arena {
    char *buffer;      /* Pointer to the actual memory buffer */
    char *current;     /* Current position in the buffer */
    size_t capacity;   /* Total capacity of the arena */
    size_t used;       /* How much memory has been used */
} Arena;

/* Helper: Align a size to ARENA_ALIGNMENT boundary */
static size_t align_up(size_t size, size_t alignment) {
    return (size + alignment - 1) & ~(alignment - 1);
}

/* Helper: Align a pointer to ARENA_ALIGNMENT boundary */
static void *align_ptr(void *ptr, size_t alignment) {
    uintptr_t aligned = ((uintptr_t)ptr + alignment - 1) & ~(uintptr_t)(alignment - 1);
    return (void *)aligned;
}

/* Create an arena with specified capacity in bytes */
Arena *arena_create(size_t capacity) {
    if (capacity == 0) return NULL;

    Arena *arena = (Arena *)malloc(sizeof(Arena));
    if (!arena) return NULL;

    arena->buffer = (char *)malloc(capacity);
    if (!arena->buffer) {
        free(arena);
        return NULL;
    }

    arena->current = arena->buffer;
    arena->capacity = capacity;
    arena->used = 0;

    return arena;
}

/* Allocate memory from the arena with specified alignment */
void *arena_alloc(Arena *arena, size_t size) {
    if (!arena || size == 0) return NULL;

    /* Align the current position */
    void *aligned = align_ptr(arena->current, ARENA_ALIGNMENT);

    /* Calculate the new current pointer after allocation */
    char *next = (char *)aligned + size;

    /* Check if we have enough space (including alignment padding) */
    size_t padding = (size_t)((char *)aligned - arena->current);
    if (padding + size > arena->capacity - arena->used) {
        return NULL;  /* Not enough memory */
    }

    /* Update the arena state */
    arena->current = next;
    arena->used += padding + size;

    return aligned;
}

/* Reset the arena (makes all memory available again) */
void arena_reset(Arena *arena) {
    if (!arena) return;

    arena->current = arena->buffer;
    arena->used = 0;
}

/* Destroy the arena and free all memory */
void arena_destroy(Arena *arena) {
    if (!arena) return;

    free(arena->buffer);
    free(arena);
}

/* Optional: Get arena statistics */
typedef struct ArenaStats {
    size_t capacity;
    size_t used;
    size_t free;
} ArenaStats;

ArenaStats arena_stats(const Arena *arena) {
    ArenaStats stats = {0, 0, 0};
    if (arena) {
        stats.capacity = arena->capacity;
        stats.used = arena->used;
        stats.free = arena->capacity - arena->used;
    }
    return stats;
}

/* Example usage */
#ifdef EXAMPLE_USAGE
#include <stdio.h>

int main(void) {
    Arena *arena = arena_create(1024 * 1024); /* 1MB arena */
    if (!arena) {
        fprintf(stderr, "Failed to create arena\n");
        return 1;
    }

    /* Allocate some memory */
    int *arr = (int *)arena_alloc(arena, 10 * sizeof(int));
    double *val = (double *)arena_alloc(arena, sizeof(double));

    if (arr) {
        for (int i = 0; i < 10; i++) {
            arr[i] = i * 100;
        }
    }

    if (val) {
        *val = 3.14159;
    }

    /* Get statistics */
    ArenaStats stats = arena_stats(arena);
    printf("Arena: %zu bytes used, %zu bytes free\n", stats.used, stats.free);

    /* Reset the arena (like a "clear" operation) */
    arena_reset(arena);

    /* Allocate again */
    char *str = (char *)arena_alloc(arena, 100);
    if (str) {
        snprintf(str, 100, "Hello from arena!");
        printf("String: %s\n", str);
    }

    stats = arena_stats(arena);
    printf("After reset: %zu bytes used\n", stats.used);

    arena_destroy(arena);

    return 0;
}
#endif
```

## Key Features:

1. **Simple Design**: Linear allocator with reset functionality
2. **Memory Alignment**: All allocations are aligned to 16-byte boundaries (suitable for most modern CPU architectures and SIMD operations)
3. **No Fragmentation**: Memory is allocated sequentially from a single block
4. **Fast Operations**: Allocation is O(1) - just a pointer increment
5. **Safe**: Checks for NULL pointers and insufficient memory

## Memory Layout:
```
+------------------+
| Arena metadata   |
+------------------+
| Buffer start     |
|                  |
| [Free space]     |
|                  |
| Current pointer  |
|                  |
| [Used space]     |
|                  |
| Buffer end       |
+------------------+
```

## How It Works:

1. **`arena_create(capacity)`**: Allocates a single contiguous block of memory of the specified size
2. **`arena_alloc(arena, size)`**: Moves the current pointer forward (aligned to 16 bytes) and returns the previous position
3. **`arena_reset(arena)`**: Resets the current pointer to the beginning of the buffer
4. **`arena_destroy(arena)`**: Frees all memory associated with the arena

## Usage Patterns:

- Perfect for temporary allocations in algorithms, parsing, or game development
- Ideal when you need to allocate many small objects and free them all at once
- Great for performance-critical code where malloc/free overhead is unacceptable

To compile and run the example:
```bash
gcc -DEXAMPLE_USAGE arena.c -o arena
./arena
```

