Here's a C hash table implementation with open addressing, linear probing, string keys, and `void*` values:

```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Constants
#define HT_INITIAL_CAPACITY 16
#define HT_LOAD_FACTOR 0.7
#define HT_DELETED (void*)-1

// Hash table entry structure
typedef struct {
    char* key;
    void* value;
    int occupied; // 1 = occupied, 0 = empty, -1 = deleted (tombstone)
} HTEntry;

// Hash table structure
typedef struct {
    HTEntry* entries;
    size_t size;     // Number of occupied entries
    size_t capacity; // Total capacity of the hash table
} HashTable;

// djb2 hash function for strings
static unsigned long hash_string(const char* key) {
    unsigned long hash = 5381;
    int c;

    while ((c = *key++)) {
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    }

    return hash;
}

// Find the index for a key, handling collisions with linear probing
static size_t find_index(HashTable* table, const char* key, int for_insert) {
    unsigned long hash = hash_string(key);
    size_t index = hash % table->capacity;

    while (1) {
        HTEntry* entry = &table->entries[index];

        // Empty slot found
        if (entry->occupied == 0) {
            return index;
        }

        // Key found (or tombstone if for_insert)
        if (entry->occupied == 1 && strcmp(entry->key, key) == 0) {
            return index;
        }

        // For insert, tombstone can be used
        if (for_insert && entry->occupied == -1) {
            return index;
        }

        // Linear probing
        index = (index + 1) % table->capacity;
    }
}

// Create a new hash table
HashTable* ht_create(void) {
    HashTable* table = malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->capacity = HT_INITIAL_CAPACITY;
    table->size = 0;
    table->entries = calloc(table->capacity, sizeof(HTEntry));

    if (!table->entries) {
        free(table);
        return NULL;
    }

    return table;
}

// Resize the hash table
static int ht_resize(HashTable* table, size_t new_capacity) {
    HTEntry* old_entries = table->entries;
    size_t old_capacity = table->capacity;

    table->entries = calloc(new_capacity, sizeof(HTEntry));
    if (!table->entries) {
        table->entries = old_entries;
        return 0;
    }

    table->capacity = new_capacity;
    table->size = 0;

    // Rehash all occupied entries
    for (size_t i = 0; i < old_capacity; i++) {
        if (old_entries[i].occupied == 1) {
            size_t index = find_index(table, old_entries[i].key, 1);
            table->entries[index] = old_entries[i];
            table->size++;
        }
    }

    free(old_entries);
    return 1;
}

// Set a key-value pair in the hash table
int ht_set(HashTable* table, const char* key, void* value) {
    if (!table || !key) return 0;

    // Check if we need to resize
    if (table->size >= table->capacity * HT_LOAD_FACTOR) {
        if (!ht_resize(table, table->capacity * 2)) {
            return 0;
        }
    }

    size_t index = find_index(table, key, 1);
    HTEntry* entry = &table->entries[index];

    // If this is a new entry
    if (entry->occupied != 1) {
        // Free old key if this is a tombstone
        if (entry->occupied == -1) {
            free(entry->key);
        }

        // Copy the key
        entry->key = malloc(strlen(key) + 1);
        if (!entry->key) return 0;
        strcpy(entry->key, key);

        table->size++;
    }

    // Update value
    entry->value = value;
    entry->occupied = 1;

    return 1;
}

// Get a value by key
void* ht_get(HashTable* table, const char* key) {
    if (!table || !key) return NULL;

    size_t index = find_index(table, key, 0);
    HTEntry* entry = &table->entries[index];

    if (entry->occupied == 1 && strcmp(entry->key, key) == 0) {
        return entry->value;
    }

    return NULL;
}

// Delete a key-value pair from the hash table
int ht_delete(HashTable* table, const char* key) {
    if (!table || !key) return 0;

    size_t index = find_index(table, key, 0);
    HTEntry* entry = &table->entries[index];

    if (entry->occupied == 1 && strcmp(entry->key, key) == 0) {
        // Mark as deleted (tombstone)
        entry->occupied = -1;
        entry->value = NULL;
        // Don't free key yet - needed for probing
        table->size--;
        return 1;
    }

    return 0;
}

// Destroy the hash table and free all memory
void ht_destroy(HashTable* table) {
    if (!table) return;

    // Free all keys
    for (size_t i = 0; i < table->capacity; i++) {
        if (table->entries[i].occupied == 1) {
            free(table->entries[i].key);
        }
    }

    // Free entries array and table
    free(table->entries);
    free(table);
}

// Example usage
int main(void) {
    // Create hash table
    HashTable* ht = ht_create();
    if (!ht) {
        fprintf(stderr, "Failed to create hash table\n");
        return 1;
    }

    // Create some sample data
    char* name = malloc(20);
    strcpy(name, "Alice");
    int* age = malloc(sizeof(int));
    *age = 30;

    // Set values
    ht_set(ht, "name", name);
    ht_set(ht, "age", age);
    ht_set(ht, "occupation", strdup("Engineer"));

    // Get values
    printf("Name: %s\n", (char*)ht_get(ht, "name"));
    printf("Age: %d\n", *(int*)ht_get(ht, "age"));
    printf("Occupation: %s\n", (char*)ht_get(ht, "occupation"));

    // Update a value
    int* new_age = malloc(sizeof(int));
    *new_age = 31;
    ht_set(ht, "age", new_age);
    free(age); // Free old value

    printf("Updated Age: %d\n", *(int*)ht_get(ht, "age"));

    // Delete a value
    if (ht_delete(ht, "occupation")) {
        printf("Deleted occupation\n");
    }
    printf("Occupation after delete: %s\n", 
           ht_get(ht, "occupation") ? "exists" : "NULL");

    // Clean up
    // Note: In a real application, you'd want to free values too
    free(name);
    free(new_age);

    ht_destroy(ht);

    return 0;
}
