// UNDEFINED BEHAVIOR: Accessing memory after it's freed
void use_after_free_undefined(void) {
    int *ptr = malloc(sizeof(int));
    if (!ptr) return;

    *ptr = 42;
    printf("Before free: *ptr = %d\n", *ptr);

    free(ptr);

    // Using pointer after free - undefined behavior!
    // The pointer is now dangling, and access could:
    // 1. Return garbage data
    // 2. Cause a segmentation fault
    // 3. Appear to work but be dangerous
    int value = *ptr; // UB: use-after-free
    printf("After free (UB): *ptr = %d\n", value);
}

// CORRECTED: Set pointer to NULL after freeing
void use_after_free_correct(void) {
    int *ptr = malloc(sizeof(int));
    if (!ptr) return;

    *ptr = 42;
    printf("Before free: *ptr = %d\n", *ptr);

    free(ptr);
    ptr = NULL; // Good practice: prevent use-after-free

    // Now any use would be caught (if checking for NULL)
    if (ptr == NULL) {
