use std::fmt;

/// Custom error type for parsing operations with bounds checking.
#[derive(Debug)]
pub enum ParseError {
    NotEnoughBytes {
        needed: usize,
        available: usize,
    },
    VarintOverflow,
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseError::NotEnoughBytes { needed, available } => {
                write!(f, "Not enough bytes: needed {} available {}", needed, available)
            }
            ParseError::VarintOverflow => write!(f, "Varint too large to fit in u64"),
        }
    }
}

impl std::error::Error for ParseError {}

/// Parse a little-endian u64 from the given byte slice.
/// Returns `Err(ParseError::NotEnoughBytes)` if the slice is shorter than 8 bytes.
pub fn parse_u64_le(data: &[u8]) -> Result<u64, ParseError> {
    if data.len() < 8 {
        return Err(ParseError::NotEnoughBytes {
            needed: 8,
            available: data.len(),
        });
    }
    // SAFETY: we already verified `data.len() >= 8`
    let array: [u8; 8] = data[..8].try_into().map_err(|_| ParseError::NotEnoughBytes {
        needed: 8,
        available: data.len(),
    })?;
    Ok(u64::from_le_bytes(array))
}

/// Parse a protobuf‑style varint (little‑endian, variable‑length) from the given byte slice.
/// Returns `Ok(u64)` on success, or an appropriate `ParseError`:
/// - `VarintOverflow` if the value doesn't fit in a u64 or exceeds 10 bytes.
/// - `NotEnoughBytes` if the slice ends without a terminating byte.
pub fn parse_varint(data: &[u8]) -> Result<u64, ParseError> {
    let mut result: u64 = 0;
    let mut shift: u32 = 0;
    let mut i = 0;

    while i < data.len() {
        let byte = data[i];
        result |= ((byte as u64) & 0x7F) << shift;
        shift += 7;
        i += 1;

        // u64 can only hold 64 bits; more than 10 continuation bytes is always an overflow
        if shift > 63 {
            return Err(ParseError::VarintOverflow);
        }

        // Termination bit (high bit clear) found -> return accumulated value
        if (byte & 0x80) == 0 {
            return Ok(result);
        }

        // If we consumed all bytes and the last one still has the continuation bit,
        // the varint is incomplete (not enough bytes) or overflow (if we already hit bit 64).
        if i == data.len() {
            // Continuation bit set on the last byte means we need at least one more byte.
            // If shift is already > 63 we'd have returned VarintOverflow above, so this is NotEnoughBytes.
            return Err(ParseError::NotEnoughBytes {
                needed: i + 1, // we need one more byte beyond what we have
                available: 0,
            });
        }
    }

    // Empty slice reached without reading any byte (handled by the loop condition,
    // but kept for completeness)
    Err(ParseError::NotEnoughBytes {
        needed: 1,
        available: 0,
    })
}

// ---------------------------------------------------------------------------
// Example usage
// ---------------------------------------------------------------------------
fn main() {
    let payload: &[u8] = &[
        0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, // little-endian u64 = 0x0807060504030201
        0xAA, 0x05,                                         // varint: 0x05 | (0xAA & 0x7F) << 7 = 5 | 10 << 7 = 5 + 1280 = 1285
    ];

    match parse_u64_le(&payload[..8]) {
        Ok(val) => println!("Little-endian u64: {}", val),
        Err(e) => eprintln!("u64 error: {}", e),
    }

    match parse_varint(&payload[8..]) {
        Ok(val) => println!("Varint: {}", val),
        Err(e) => eprintln!("Varint error: {}", e),
    }

    // Demonstrate bounds checking
    let short: &[u8] = &[0x01, 0x02, 0x03];
    match parse_u64_le(short) {
        Ok(_) => unreachable!(),
        Err(e) => println!("Expected error on short slice: {}", e),
    }
}
```

### Key details:
- **`ParseError`** enum has two variants:
  - `NotEnoughBytes { needed, available }` — tells you exactly how many bytes were required vs how many were present.
  - `VarintOverflow` — triggered if a varint exceeds 64 bits or exceeds the standard 10‑byte limit.
- **`parse_u64_le`** checks `data.len() >= 8` before slicing, then converts the first 8 bytes to a `u64` using `from_le_bytes`.
- **`parse_varint`** follows the standard protobuf varint encoding: each byte contributes 7 data bits, the MSB signals “more bytes follow”. It safely handles:
  - Successful termination
  - Incomplete input (slice ends with continuation bit set)
  - Value overflow (> 64 bits)
- Both functions return `Result<u64, ParseError>`, giving you full bounds checking and a custom, informative error type.

