#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define VECTOR_INIT_CAPACITY 8

typedef struct {
    int *data;
    size_t size;
    size_t capacity;
} Vector;

// Create a new vector
Vector* vector_new() {
    Vector *v = malloc(sizeof(Vector));
    if (!v) return NULL;

    v->capacity = VECTOR_INIT_CAPACITY;
    v->size = 0;
    v->data = malloc(v->capacity * sizeof(int));

    if (!v->data) {
        free(v);
        return NULL;
    }

    return v;
}

// Free the vector and its data
void vector_free(Vector *v) {
    if (v) {
        free(v->data);
        free(v);
    }
}

// Reserve at least 'cap' elements
int vector_reserve(Vector *v, size_t cap) {
    if (!v) return 0;
    if (cap <= v->capacity) return 1;

    int *new_data = realloc(v->data, cap * sizeof(int));
    if (!new_data) return 0;

    v->data = new_data;
    v->capacity = cap;
    return 1;
}

// Helper function to grow capacity
static int vector_grow(Vector *v, size_t additional) {
    size_t new_capacity = v->capacity;

    // Amortized growth: double capacity or add enough
    while (new_capacity < v->size + additional) {
        new_capacity *= 2;
        // Prevent overflow
        if (new_capacity == 0) new_capacity = 1;
    }

    return vector_reserve(v, new_capacity);
}

// Add element to the end (amortized O(1))
int vector_push(Vector *v, int value) {
    if (!v) return 0;

    // Grow if needed
    if (v->size >= v->capacity) {
        if (!vector_grow(v, 1)) return 0;
    }

    v->data[v->size++] = value;
    return 1;
}

// Remove and return last element
int vector_pop(Vector *v, int *value) {
    if (!v || v->size == 0) return 0;

    *value = v->data[--v->size];

    // Optional: shrink if too empty
    // if (v->size > 0 && v->size <= v->capacity / 4) {
    //     vector_reserve(v, v->capacity / 2);
    // }

    return 1;
}

// Reduce capacity to fit current size
void vector_shrink_to_fit(Vector *v) {
    if (!v || v->size == 0) {
        if (v) {
            free(v->data);
            v->data = NULL;
            v->capacity = 0;
        }
        return;
    }

    int *new_data = realloc(v->data, v->size * sizeof(int));
    if (new_data) {
        v->data = new_data;
        v->capacity = v->size;
    }
}

// Example usage
