    Vector *v = vector_new();
    if (!v) {
        fprintf(stderr, "Failed to create vector\n");
        return 1;
    }

    printf("Initial capacity: %zu\n", v->capacity);

    // Push elements to demonstrate growth
    for (int i = 0; i < 20; i++) {
        if (!vector_push(v, i * 10)) {
            fprintf(stderr, "Failed to push element %d\n", i);
            vector_free(v);
            return 1;
        }
    }

    printf("After pushing 20 elements: size=%zu, capacity=%zu\n", 
           v->size, v->capacity);

    // Pop some elements
    int value;
    for (int i = 0; i < 15; i++) {
        if (vector_pop(v, &value)) {
            printf("Popped: %d\n", value);
        }
    }

    printf("After popping 15: size=%zu, capacity=%zu\n", 
           v->size, v->capacity);

    // Shrink to fit
    vector_shrink_to_fit(v);
    printf("After shrink_to_fit: size=%zu, capacity=%zu\n", 
           v->size, v->capacity);

    // Reserve more space
    if (vector_reserve(v, 50)) {
        printf("After reserve(50): size=%zu, capacity=%zu\n", 
               v->size, v->capacity);
    }

    vector_free(v);
    return 0;
}
