Here's a clean, self-contained C implementation. The phrase *"offset 8"* is interpreted as a **zero-point offset of 8** (common in integer quantization so that all 4-bit codes are unsigned in `[0, 15]`). Each byte packs two 4‑bit nibbles (MSB first). The functions accept a byte offset for the output buffer, but you can set it to `0` if you don't need an initial stride.

```c
#include <stdint.h>
#include <stdlib.h>
#include <math.h>

/* ----------------------------------------------------------------------
 * Quantize float32 array to packed 4‑bit values (two nibbles per byte)
 * with a zero-point offset of 8.  Output bytes start at @byte_offset.
 *
 *   input  – float array of length n
 *   scale  – per-block scale factor (float * value = approx integer)
 *   n      – number of float values to quantize
 *   output – uint8_t buffer; must have at least (n+1)/2 bytes available
 *   byte_offset – starting byte index in output where packing begins
 *
 *  Packing order: for each pair (q0, q1) -> byte = (q0 << 4) | q1
 *  (q0 is the high nibble, q1 is the low nibble)
 *  If n is odd, the last nibble is padded with 0.
 * ---------------------------------------------------------------------- */
void quantize_float_to_int4(
    const float*  input,
    float         scale,
    int           n,
    uint8_t*      output,
    size_t        byte_offset)
{
    if (!input || !output || n <= 0) return;

    size_t out_idx = byte_offset;
    /* Process two floats per output byte */
    for (int i = 0; i < n; i += 2) {
        /* ---- quantize first value ---- */
        int q0 = (int)roundf(input[i] / scale) + 8;   /* apply offset 8 */
        if (q0 > 15) q0 = 15;
        if (q0 < 0)  q0 = 0;

        /* ---- quantize second value (if present) ---- */
        int q1 = 0;
        if (i + 1 < n) {
            q1 = (int)roundf(input[i + 1] / scale) + 8;
            if (q1 > 15) q1 = 15;
            if (q1 < 0)  q1 = 0;
        } else {
            /* padding nibble – keep 0 so dequantize yields 0 */
        }

        /* pack: high nibble = q0, low nibble = q1 */
        output[out_idx] = ((uint8_t)q0 << 4) | (uint8_t)q1;
        out_idx++;
    }
}

/* ----------------------------------------------------------------------
 * Dequantize packed 4‑bit values back to float32 using the same per‑block
 * scale and the zero-point offset of 8.
 *
 *   input   – packed uint8_t array (two nibbles per byte)
 *   scale   – same per‑block scale used during quantization
 *   n       – number of float values to reconstruct
 *   output  – float array of length n
 * ---------------------------------------------------------------------- */
void dequantize_int4_to_float(
    const uint8_t* input,
    float          scale,
    int            n,
    float*         output)
{
    if (!input || !output || n <= 0) return;

    for (int i = 0; i < n; i += 2) {
        size_t byte_idx = i / 2;          /* which byte holds this pair */
        uint8_t byte    = input[byte_idx];

        /* extract nibbles (MSB first: high = byte>>4, low = byte&0xF) */
        int q0 = (int)(byte >> 4) - 8;    /* remove offset 8 */
        int q1 = (int)(byte & 0xF) - 8;

        /* clamp just in case of edge values */
        if (q0 > 15) q0 = 15;
        if (q0 < 0)  q0 = 0;
        if (q1 > 15) q1 = 15;
        if (q1 < 0)  q1 = 0;

        /* recover floats */
        output[i]     = q0 * scale;
        if (i + 1 < n)
            output[i+1] = q1 * scale;
    }
}
```

### Quick usage example
```c
int main(void) {
    float data[] = { 1.2f, -0.5f, 3.7f, 0.0f };
    float scale  = 0.5f;
    int n        = 4;
    uint8_t buf[2] = {0};          /* 4 floats -> 2 bytes */

    quantize_float_to_int4(data, scale, n, buf, 0);

    float recovered[n];
    dequantize_int4_to_float(buf, scale, n, recovered);

    /* recovered ≈ { 1.2, -0.5, 3.7, 0.0 } */
    return 0;
}
```

### Notes
* **Zero‑point offset 8** means the actual float value ≈ `(packed_nibble - 8) * scale`. This keeps all 4‑bit codes in `[0, 15]` and enables symmetric unsigned storage.
* Packing order is **MSB‑first** (`high_nibble << 4 | low_nibble`). Swap the shift if you need LSB‑first.
* The `byte_offset` parameter lets you start writing at any byte index in a pre‑allocated buffer (e.g., `byte_offset = 8` would skip the first 8 bytes).
* Edge case: if `n` is odd, the last padding nibble is `0`; dequantize recovers `0` for that element. Adjust padding if you need a different convention.

Here's a C function that tokenizes a string by whitespace without modifying the input, along with a cleanup function:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

/**
 * Tokenizes a string by whitespace without modifying the input.
 * 
 * @param str The input string to tokenize (must not be modified).
 * @param num_tokens Pointer to store the number of tokens found.
 * @return Array of token strings (must be freed with free_tokens),
 *         or NULL if no tokens are found.
 */
char **tokenize(const char *str, size_t *num_tokens) {
    if (!str || !num_tokens) {
        return NULL;
    }

    // First pass: count tokens
    size_t count = 0;
    const char *ptr = str;

    while (*ptr) {
        // Skip whitespace
        while (*ptr && isspace((unsigned char)*ptr)) {
            ptr++;
        }

        // If we reached end of string, break
        if (!*ptr) {
            break;
        }

        // We found a token
        count++;

        // Skip non-whitespace
        while (*ptr && !isspace((unsigned char)*ptr)) {
            ptr++;
        }
    }

    if (count == 0) {
        *num_tokens = 0;
        return NULL;
    }

    // Allocate array of pointers (plus NULL terminator)
    char **tokens = malloc((count + 1) * sizeof(char *));
    if (!tokens) {
        *num_tokens = 0;
        return NULL;
    }

    // Second pass: extract tokens
    ptr = str;
    size_t i = 0;

    while (*ptr && i < count) {
        // Skip whitespace
        while (*ptr && isspace((unsigned char)*ptr)) {
            ptr++;
        }

        if (!*ptr) {
            break;
        }

        // Find end of current token
        const char *token_start = ptr;
        while (*ptr && !isspace((unsigned char)*ptr)) {
            ptr++;
        }

        // Calculate token length and copy
        size_t token_len = ptr - token_start;
        char *token = malloc(token_len + 1);

        if (!token) {
            // Cleanup on allocation failure
            for (size_t j = 0; j < i; j++) {
                free(tokens[j]);
            }
            free(tokens);
            *num_tokens = 0;
            return NULL;
        }

        // Copy token and null-terminate
        memcpy(token, token_start, token_len);
        token[token_len] = '\0';

        tokens[i++] = token;
    }

    // Null-terminate the array
    tokens[i] = NULL;
    *num_tokens = i;

    return tokens;
}

/**
 * Frees the memory allocated by tokenize().
 * 
 * @param tokens The array of token strings to free.
 */
void free_tokens(char **tokens) {
    if (!tokens) {
        return;
    }

    // Free each token string
    for (size_t i = 0; tokens[i] != NULL; i++) {
        free(tokens[i]);
    }

    // Free the array itself
    free(tokens);
}

// Example usage
int main() {
    const char *input = "  Hello   world! This is   a test string.  ";
    size_t num_tokens = 0;

    printf("Original string: \"%s\"\n\n", input);

    char **tokens = tokenize(input, &num_tokens);

    if (tokens) {
        printf("Number of tokens: %zu\n", num_tokens);
        printf("Tokens:\n");
        for (size_t i = 0; i < num_tokens; i++) {
            printf("  [%zu]: \"%s\"\n", i, tokens[i]);
        }

        // Verify original string is unchanged
        printf("\nOriginal string after tokenization: \"%s\"\n", input);

        // Free the tokens
        free_tokens(tokens);
    } else {
        printf("No tokens found or memory allocation failed.\n");
    }

    return 0;
}
```

## Key Features:

1. **Input Preservation**: The function only reads the input string, never modifies it
2. **Two-Pass Approach**: First pass counts tokens, second pass extracts them
3. **Proper Memory Management**: 
   - `tokenize()` allocates memory for both the token array and individual tokens
   - `free_tokens()` properly frees all allocated memory
4. **Safety Features**:
   - Handles NULL inputs gracefully
   - Cleans up on allocation failures
   - Null-terminates the token array
   - Properly handles edge cases (empty strings, strings with only whitespace)
5. **Memory Efficiency**: Uses `memcpy` instead of repeated `strncpy` for token copying

## Usage:

1. Call `tokenize()` with your input string and a pointer to store the token count
2. Process the tokens as needed
3. Always call `free_tokens()` when done to prevent memory leaks

The function splits on any whitespace (spaces, tabs, newlines, etc.) and treats consecutive whitespace as a single delimiter.

Here's a C function that memory-maps a file read-only with a fallback to `fread`, along with a helper structure and cleanup function:

```c
#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <errno.h>

typedef struct {
    void *data;
    size_t size;
    int is_mmap;  // 1 = mmap'd, 0 = fread'd
} FileContent;

/**
 * Load file contents into memory, attempting mmap first, falling back to fread.
 * 
 * @param filename Path to file to load
 * @param out Pointer to FileContent structure to fill
 * @return 0 on success, -1 on failure (with errno set)
 */
int load_file_contents(const char *filename, FileContent *out) {
    if (!filename || !out) {
        errno = EINVAL;
        return -1;
    }

    // Initialize output structure
    out->data = NULL;
    out->size = 0;
    out->is_mmap = 0;

    // Try mmap approach first
    int fd = open(filename, O_RDONLY);
    if (fd != -1) {
        struct stat st;
        if (fstat(fd, &st) == 0 && st.st_size > 0) {
            void *map = mmap(NULL, st.st_size, PROT_READ, MAP_PRIVATE, fd, 0);
            if (map != MAP_FAILED) {
                out->data = map;
                out->size = st.st_size;
                out->is_mmap = 1;
                close(fd);
                return 0;
            }
        }
        close(fd);
    }

    // Fallback to fread approach
    FILE *fp = fopen(filename, "rb");
    if (!fp) {
        return -1;
    }

    // Get file size
    if (fseek(fp, 0, SEEK_END) != 0) {
        fclose(fp);
        return -1;
    }

    long file_size = ftell(fp);
    if (file_size < 0) {
        fclose(fp);
        return -1;
    }

    if (fseek(fp, 0, SEEK_SET) != 0) {
        fclose(fp);
        return -1;
    }

    // Allocate memory and read file
    char *buffer = malloc(file_size + 1);  // +1 for null terminator if needed
    if (!buffer) {
        fclose(fp);
        return -1;
    }

    size_t bytes_read = fread(buffer, 1, file_size, fp);
    fclose(fp);

    if (bytes_read != (size_t)file_size) {
        free(buffer);
        return -1;
    }

    out->data = buffer;
    out->size = file_size;
    out->is_mmap = 0;

    return 0;
}

/**
 * Clean up file contents loaded by load_file_contents.
 * 
 * @param content Pointer to FileContent structure to clean up
 */
void free_file_contents(FileContent *content) {
    if (!content) return;

    if (content->data) {
        if (content->is_mmap) {
            munmap(content->data, content->size);
        } else {
            free(content->data);
        }
    }

    content->data = NULL;
    content->size = 0;
    content->is_mmap = 0;
}

/* Example usage */
#ifdef EXAMPLE_USAGE
int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    FileContent file;
    if (load_file_contents(argv[1], &file) == 0) {
        printf("File loaded successfully (%s)\n", 
               file.is_mmap ? "mmap" : "fread");
        printf("Size: %zu bytes\n", file.size);

        // Process file contents here...
        // For example, just print first 100 bytes if available
        if (file.size > 0) {
            size_t display_size = file.size > 100 ? 100 : file.size;
            printf("First %zu bytes: ", display_size);
            for (size_t i = 0; i < display_size; i++) {
                printf("%c", ((char*)file.data)[i]);
            }
            printf("\n");
        }

        free_file_contents(&file);
    } else {
        perror("Failed to load file");
        return 1;
    }

    return 0;
}
#endif
```

## Key Features:

1. **Unified Interface**: The same `FileContent` structure is used regardless of the loading method
2. **Automatic Fallback**: Tries `mmap` first, then falls back to `fread` if `mmap` fails
3. **Proper Cleanup**: The `free_file_contents()` function handles both `munmap()` and `free()` appropriately
4. **Error Handling**: Returns proper error codes and sets `errno`
5. **Safe Memory Management**: Cleans up resources on failure paths

## Usage Notes:

- Call `load_file_contents()` to load the file
- Call `free_file_contents()` when done to release resources
- Check `file.is_mmap` if you need to know which method was used
- The function returns -1 on failure with `errno` set to the error code
- For files that may change during reading, `mmap` provides automatic synchronization, while `fread` creates a snapshot

## Advantages of mmap Approach:
- No explicit read operation required
- Virtual memory system handles caching and paging
- Multiple processes can share the same mapped memory
- File changes are automatically reflected in the mapped region

## Advantages of fread Fallback:
- Works on systems without mmap support
- Works with non-seekable streams
- May be faster for very small files (avoids mmap overhead)
- More straightforward error handling in some cases

This implementation provides a robust, cross-platform compatible solution that leverages the advantages of memory mapping when available while maintaining compatibility through the fallback mechanism.

# Binary File Header Parser in C

Here's a complete C implementation with struct definition, endianness detection, and robust error handling:

```c
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <errno.h>

// Header structure with packed attribute to avoid padding
typedef struct __attribute__((packed)) {
    char magic[4];        // Magic bytes for identification
    uint32_t version;     // Version number
    uint64_t count;       // Count field
} FileHeader;

// Expected magic bytes
static const char EXPECTED_MAGIC[4] = {0x42, 0x49, 0x4E, 0x41}; // "BINA"

// Endianness detection structure for runtime checking
typedef union {
    uint32_t value;
    uint8_t bytes[4];
} EndianTest;

// Error codes for detailed error reporting
typedef enum {
    HEADER_OK = 0,
    HEADER_READ_ERROR,
    HEADER_MAGIC_ERROR,
    HEADER_ENDIAN_ERROR,
    HEADER_VERSION_ERROR,
    HEADER_NULL_ERROR
} HeaderError;

// Error messages for each error code
static const char* header_error_messages[] = {
    "Success",
    "Failed to read header from file",
    "Invalid magic bytes",
    "Endianness mismatch detected",
    "Unsupported version",
    "NULL pointer provided"
};

/**
 * Detect system endianness at runtime
 * @return 1 if little-endian, 0 if big-endian
 */
int is_little_endian(void) {
    EndianTest test;
    test.value = 1;
    return (test.bytes[0] == 1);
}

/**
 * Swap bytes for 32-bit integer
 */
uint32_t swap_uint32(uint32_t value) {
    return ((value & 0x000000FF) << 24) |
           ((value & 0x0000FF00) << 8)  |
           ((value & 0x00FF0000) >> 8)  |
           ((value & 0xFF000000) >> 24);
}

/**
 * Swap bytes for 64-bit integer
 */
uint64_t swap_uint64(uint64_t value) {
    return ((value & 0x00000000000000FFULL) << 56) |
           ((value & 0x000000000000FF00ULL) << 40) |
           ((value & 0x0000000000FF0000ULL) << 24) |
           ((value & 0x00000000FF000000ULL) << 8)  |
           ((value & 0x000000FF00000000ULL) >> 8)  |
           ((value & 0x0000FF0000000000ULL) >> 24) |
           ((value & 0x00FF000000000000ULL) >> 40) |
           ((value & 0xFF00000000000000ULL) >> 56);
}

/**
 * Check if magic bytes match expected pattern
 * @return 0 if match, non-zero otherwise
 */
int validate_magic(const char* magic) {
    return memcmp(magic, EXPECTED_MAGIC, 4) != 0;
}

/**
 * Parse binary file header with endianness handling
 * @param file_path Path to binary file
 * @param header Pointer to structure to populate
 * @return Error code (HEADER_OK on success)
 */
HeaderError parse_file_header(const char* file_path, FileHeader* header) {
    // Validate input
    if (!file_path || !header) {
        return HEADER_NULL_ERROR;
    }

    FILE* file = fopen(file_path, "rb");
    if (!file) {
        fprintf(stderr, "Error opening file '%s': %s\n", file_path, strerror(errno));
        return HEADER_READ_ERROR;
    }

    // Read raw bytes
    char buffer[16];  // 4 + 4 + 8 = 16 bytes total
    size_t read_count = fread(buffer, 1, 16, file);
    fclose(file);

    if (read_count != 16) {
        fprintf(stderr, "Error: File too small (read %zu of 16 bytes)\n", read_count);
        return HEADER_READ_ERROR;
    }

    // Check magic bytes (endian-independent)
    if (validate_magic(buffer)) {
        fprintf(stderr, "Error: Invalid magic bytes: 0x%02x%02x%02x%02x\n",
                (unsigned char)buffer[0],
                (unsigned char)buffer[1],
                (unsigned char)buffer[2],
                (unsigned char)buffer[3]);
        return HEADER_MAGIC_ERROR;
    }

    // Copy magic to header
    memcpy(header->magic, buffer, 4);

    // Detect system endianness
    int system_is_little = is_little_endian();
    printf("System is %s-endian\n", system_is_little ? "little" : "big");

    // Note: For this example, we assume file is stored in little-endian format.
    // In practice, you might store endianness in the header or use a fixed convention.
    int file_is_little = 1;  // Assume file is little-endian

    // Parse version (bytes 4-7)
    uint32_t version_raw;
    memcpy(&version_raw, buffer + 4, 4);

    // Parse count (bytes 8-15)
    uint64_t count_raw;
    memcpy(&count_raw, buffer + 8, 8);

    // Handle endianness conversion
    if (system_is_little != file_is_little) {
        printf("Endianness conversion needed\n");

        // Swap bytes if system and file have different endianness
        header->version = swap_uint32(version_raw);
        header->count = swap_uint64(count_raw);

        printf("Converted version: %u -> %u\n", version_raw, header->version);
        printf("Converted count: %llu -> %llu\n", 
               (unsigned long long)count_raw,
               (unsigned long long)header->count);
    } else {
        // No conversion needed
        header->version = version_raw;
        header->count = count_raw;

        printf("No endianness conversion needed\n");
        printf("Raw version: %u\n", header->version);
        printf("Raw count: %llu\n", (unsigned long long)header->count);
    }

    // Version validation (example: only version 1 is supported)
    if (header->version > 1) {
        fprintf(stderr, "Warning: Version %u may not be supported\n", header->version);
        // Still continue, but could return HEADER_VERSION_ERROR
    }

    return HEADER_OK;
}

/**
 * Create a sample binary file for testing
 */
int create_sample_file(const char* file_path) {
    FILE* file = fopen(file_path, "wb");
    if (!file) {
        fprintf(stderr, "Failed to create sample file: %s\n", strerror(errno));
        return -1;
    }

    // Magic: "BINA"
    fwrite(EXPECTED_MAGIC, 1, 4, file);

    // Version: 1 (stored as little-endian)
    uint32_t version = 1;
    fwrite(&version, 4, 1, file);

    // Count: 1234567890 (stored as little-endian)
    uint64_t count = 1234567890;
    fwrite(&count, 8, 1, file);

    fclose(file);
    printf("Created sample file: %s\n", file_path);
    return 0;
}

/**
 * Print header contents
 */
void print_header(const FileHeader* header) {
    if (!header) return;

    printf("\n=== File Header ===\n");
    printf("Magic:   0x%02x%02x%02x%02x ('%c%c%c%c')\n",
           (unsigned char)header->magic[0],
           (unsigned char)header->magic[1],
           (unsigned char)header->magic[2],
           (unsigned char)header->magic[3],
           header->magic[0],
           header->magic[1],
           header->magic[2],
           header->magic[3]);
    printf("Version: %u (0x%08x)\n", header->version, header->version);
    printf("Count:   %llu (0x%016llx)\n", 
           (unsigned long long)header->count,
           (unsigned long long)header->count);
    printf("===================\n\n");
}

// Main function for testing
int main(void) {
    const char* sample_file = "sample.bin";

    printf("=== Binary File Header Parser ===\n\n");

    // Create sample file for testing
    if (create_sample_file(sample_file) != 0) {
        return EXIT_FAILURE;
    }

    // Parse the header
    FileHeader header;
    HeaderError error = parse_file_header(sample_file, &header);

    if (error == HEADER_OK) {
        print_header(&header);
        printf("✓ Header parsed successfully\n");
    } else {
        fprintf(stderr, "✗ Error parsing header: %s\n", 
                header_error_messages[error]);
        return EXIT_FAILURE;
    }

    // Test with invalid file
    printf("\n--- Testing with invalid file ---\n");
    FILE* invalid_file = fopen("invalid.bin", "wb");
    if (invalid_file) {
        // Write invalid magic
        fwrite("XXXX", 1, 4, invalid_file);
        fwrite(&header.version, 4, 1, invalid_file);
        fwrite(&header.count, 8, 1, invalid_file);
        fclose(invalid_file);

        error = parse_file_header("invalid.bin", &header);
        if (error != HEADER_OK) {
            printf("✓ Correctly detected invalid file: %s\n", 
                   header_error_messages[error]);
        }
        remove("invalid.bin");
    }

    // Cleanup
    remove(sample_file);

    return EXIT_SUCCESS;
}
```

