Here's a clean, self-contained C implementation that scans a vocabulary array and greedily picks the longest token that matches the start of a given buffer.

```c
#include <string.h>
#include <stddef.h>

/* Result returned by the matcher */
typedef struct {
    int token_id;          /* index into the vocabulary array, -1 if no match */
    size_t length_consumed; /* number of characters consumed from the buffer */
} greedy_match_result;

/*
 * Greedily matches the longest vocabulary token at the start of `buffer`.
 *
 * @param vocabulary  Array of null-terminated C strings (the token vocabulary).
 * @param vocab_size  Number of entries in `vocabulary`.
 * @param buffer      The text buffer to match against (null-terminated or counted).
 * @param buffer_len  Length of `buffer` in bytes. Set to 0 if null-terminated and
                    you want `strlen`-based limits (not recommended for safety).
 *
 * @return            struct with the matched token id and consumed length.
 *                    token_id == -1 means no vocabulary token matched.
 */
greedy_match_result greedy_match_token(const char vocabulary[],
                                       size_t vocab_size,
                                       const char buffer[],
                                       size_t buffer_len)
{
    greedy_match_result result = { .token_id = -1, .length_consumed = 0 };

    for (size_t i = 0; i < vocab_size; ++i) {
        const char *tok = vocabulary + i;   /* assume array of pointers, adjust if needed */
        size_t tok_len = strlen(tok);
        if (tok_len == 0) continue;
        if (tok_len > buffer_len) continue;
        if (strncmp(buffer, tok, tok_len) == 0) {
            /* strictly longer than current best → greedy pick */
            if (tok_len > result.length_consumed) {
                result.token_id = (int)i;
                result.length_consumed = tok_len;
            }
        }
    }
    return result;
}
```

### Quick usage example

```c
#include <stdio.h>

int main(void) {
    const char *vocab[] = { "a", "ab", "abc", "b", "bc" };
    size_t vocab_size = sizeof(vocab) / sizeof(vocab[0]);

    const char *text = "abcde";
    size_t text_len = strlen(text);

    greedy_match_result r = greedy_match_token(vocab, vocab_size, text, text_len);

    if (r.token_id >= 0)
        printf("Matched token #%d, consumed %zu chars\n", r.token_id, r.length_consumed);
    else
        printf("No token matched.\n");

    return 0;
}
```

**Output:**
```
Matched token #2, consumed 3 chars
```

### Notes
- **Tie-breaking**: If multiple tokens have the same maximum matching length, the first one encountered in the array wins (due to the `>` comparison).
- **Safety**: Always pass `buffer_len` if the buffer might not be null-terminated, or ensure the buffer is properly null-terminated and use `0` for `buffer_len` (the check `tok_len > buffer_len` will then effectively compare against the null terminator position).
- **Case sensitivity**: Matching is case-sensitive and byte-exact, matching typical tokenization assumptions.
- **Performance**: O(`vocab_size`) scan. For large vocabularies, consider sorting by length descending or building a trie, but this satisfies the "greedy longest-match from array" requirement directly.

Here's a C function that handles UTF-8 ↔ UTF-32 conversion for single codepoints with error handling:

```c
#include <stdint.h>
#include <stddef.h>
#include <string.h>

/* Error codes */
typedef enum {
    UTF8_OK = 0,
    UTF8_ERR_INVALID_BYTE,       /* Invalid UTF-8 byte */
    UTF8_ERR_TOO_SHORT,          /* Unexpected end of sequence */
    UTF8_ERR_OVERLONG,           /* Overlong encoding */
    UTF8_ERR_INVALID_CODEPOINT,  /* Invalid Unicode codepoint */
    UTF8_ERR_BUFFER_TOO_SMALL    /* Output buffer too small */
} UTF8Error;

/**
 * Decode a single UTF-8 sequence to a UTF-32 codepoint.
 * 
 * @param utf8          Pointer to UTF-8 bytes
 * @param len           Length of UTF-8 buffer (in bytes)
 * @param codepoint     Output: decoded codepoint (UTF-32)
 * @param bytes_read    Output: number of UTF-8 bytes consumed
 * @return              UTF8_OK on success, error code otherwise
 */
UTF8Error utf8_to_utf32(const uint8_t *utf8, size_t len, 
                        uint32_t *codepoint, size_t *bytes_read)
{
    if (!utf8 || !codepoint || !bytes_read || len == 0) {
        return UTF8_ERR_INVALID_BYTE;
    }

    uint32_t cp = 0;
    size_t expected_len = 0;

    /* Check first byte to determine sequence length */
    const uint8_t first = utf8[0];

    if (first <= 0x7F) {
        /* ASCII (0xxxxxxx) */
        cp = first;
        expected_len = 1;
    } else if ((first & 0xE0) == 0xC0) {
        /* 2-byte sequence (110xxxxx) */
        cp = first & 0x1F;
        expected_len = 2;
    } else if ((first & 0xF0) == 0xE0) {
        /* 3-byte sequence (1110xxxx) */
        cp = first & 0x0F;
        expected_len = 3;
    } else if ((first & 0xF8) == 0xF0) {
        /* 4-byte sequence (11110xxx) */
        cp = first & 0x07;
        expected_len = 4;
    } else {
        /* Invalid leading byte (10xxxxxx or >11111xxx) */
        return UTF8_ERR_INVALID_BYTE;
    }

    /* Check buffer has enough bytes */
    if (len < expected_len) {
        return UTF8_ERR_TOO_SHORT;
    }

    /* Process continuation bytes */
    for (size_t i = 1; i < expected_len; i++) {
        uint8_t byte = utf8[i];
        if ((byte & 0xC0) != 0x80) {
            /* Expected continuation byte (10xxxxxx) */
            return UTF8_ERR_INVALID_BYTE;
        }
        cp = (cp << 6) | (byte & 0x3F);
    }

    /* Validation */

    /* Check for overlong encodings */
    if (expected_len == 2 && cp < 0x80) {
        return UTF8_ERR_OVERLONG;
    } else if (expected_len == 3 && cp < 0x800) {
        return UTF8_ERR_OVERLONG;
    } else if (expected_len == 4 && cp < 0x10000) {
        return UTF8_ERR_OVERLONG;
    }

    /* Check for invalid codepoints */
    if (cp > 0x10FFFF) {
        return UTF8_ERR_INVALID_CODEPOINT;
    }

    /* Check for UTF-16 surrogates (U+D800 to U+DFFF) */
    if (cp >= 0xD800 && cp <= 0xDFFF) {
        return UTF8_ERR_INVALID_CODEPOINT;
    }

    /* Check for non-characters (U+FDD0 to U+FDEF) */
    if (cp >= 0xFDD0 && cp <= 0xFDEF) {
        return UTF8_ERR_INVALID_CODEPOINT;
    }

    *codepoint = cp;
    *bytes_read = expected_len;

    return UTF8_OK;
}

/**
 * Encode a UTF-32 codepoint to UTF-8.
 * 
 * @param codepoint     Codepoint to encode (UTF-32)
 * @param utf8          Output buffer for UTF-8 bytes
 * @param len           Size of output buffer (in bytes, should be >= 4)
 * @param bytes_written Output: number of UTF-8 bytes written
 * @return              UTF8_OK on success, error code otherwise
 */
UTF8Error utf32_to_utf8(uint32_t codepoint, uint8_t *utf8, 
                        size_t len, size_t *bytes_written)
{
    if (!utf8 || !bytes_written || len == 0) {
        return UTF8_ERR_INVALID_BYTE;
    }

    /* Check for invalid codepoints */
    if (codepoint > 0x10FFFF) {
        return UTF8_ERR_INVALID_CODEPOINT;
    }

    /* Check for UTF-16 surrogates */
    if (codepoint >= 0xD800 && codepoint <= 0xDFFF) {
        return UTF8_ERR_INVALID_CODEPOINT;
    }

    /* Check for non-characters */
    if (codepoint >= 0xFDD0 && codepoint <= 0xFDEF) {
        return UTF8_ERR_INVALID_CODEPOINT;
    }

    /* Determine number of bytes needed */
    size_t num_bytes;
    if (codepoint <= 0x7F) {
        num_bytes = 1;
    } else if (codepoint <= 0x7FF) {
        num_bytes = 2;
    } else if (codepoint <= 0xFFFF) {
        num_bytes = 3;
    } else {
        num_bytes = 4;
    }

    /* Check buffer size */
    if (len < num_bytes) {
        return UTF8_ERR_BUFFER_TOO_SMALL;
    }

    /* Encode the codepoint */
    if (num_bytes == 1) {
        utf8[0] = (uint8_t)codepoint;
    } else {
        /* First byte */
        uint8_t mask = (0xFF << (8 - num_bytes)) | (0xFF >> (num_bytes + 1));
        utf8[0] = (uint8_t)(mask | (codepoint >> (6 * (num_bytes - 1))));

        /* Continuation bytes */
        for (size_t i = 1; i < num_bytes; i++) {
            utf8[i] = 0x80 | ((codepoint >> (6 * (num_bytes - i - 1))) & 0x3F);
        }
    }

    *bytes_written = num_bytes;

    return UTF8_OK;
}

/* Helper function to convert error codes to strings */
const char *utf8_error_string(UTF8Error error)
{
    switch (error) {
        case UTF8_OK:                 return "Success";
        case UTF8_ERR_INVALID_BYTE:   return "Invalid UTF-8 byte";
        case UTF8_ERR_TOO_SHORT:      return "Unexpected end of sequence";
        case UTF8_ERR_OVERLONG:       return "Overlong encoding";
        case UTF8_ERR_INVALID_CODEPOINT: return "Invalid Unicode codepoint";
        case UTF8_ERR_BUFFER_TOO_SMALL:  return "Output buffer too small";
        default:                      return "Unknown error";
    }
}

/* Example usage */
#ifdef UTF8_EXAMPLE
#include <stdio.h>

int main(void) {
    /* Test UTF-8 to UTF-32 */
    const uint8_t test_utf8[] = {0xE4, 0xB8, 0xA5, 0x00}; /* 你 (U+4F60) */
    uint32_t codepoint;
    size_t bytes_read;

    UTF8Error err = utf8_to_utf32(test_utf8, strlen((char*)test_utf8), 
                                  &codepoint, &bytes_read);
    if (err == UTF8_OK) {
        printf("UTF-8 → UTF-32: U+%04X (consumed %zu bytes)\n", 
               codepoint, bytes_read);
    } else {
        printf("Error: %s\n", utf8_error_string(err));
    }

    /* Test UTF-32 to UTF-8 */
    uint8_t output[4];
    size_t bytes_written;

    err = utf32_to_utf8(0x1F600, output, sizeof(output), &bytes_written); /* 😀 */
    if (err == UTF8_OK) {
        printf("UTF-32 → UTF-8: ");
        for (size_t i = 0; i < bytes_written; i++) {
            printf("0x%02X ", output[i]);
        }
        printf("(%zu bytes)\n", bytes_written);
    }

    /* Test error handling */
    uint8_t invalid[] = {0xC0, 0x80, 0x00}; /* Overlong encoding */
    err = utf8_to_utf32(invalid, 2, &codepoint, &bytes_read);
    printf("Overlong test: %s\n", utf8_error_string(err));

    return 0;
}
#endif
```

## Key Features

1. **Comprehensive Validation:**
   - Checks for invalid UTF-8 byte sequences
   - Detects overlong encodings (security vulnerability)
   - Rejects UTF-16 surrogates (U+D800–U+DFFF)
   - Rejects Unicode non-characters (U+FDD0–U+FDEF)
   - Ensures codepoints ≤ U+10FFFF (maximum Unicode value)

2. **Safety:**
   - Buffer size checking for both input and output
   - Prevents reading beyond buffer boundaries
   - Clear error codes for different failure modes
   - Null pointer checks

3. **Standard Compliance:**
   - Follows RFC 3629 (UTF-8)
   - Handles all valid Unicode codepoints
   - Proper UTF-8 encoding patterns

4. **Usage Notes:**
   - For UTF-32, use `uint32_t` (always 32-bit)
   - UTF-8 sequences are 1–4 bytes
   - Always check return values for errors
   - Output buffer should be at least 4 bytes for UTF-8

5. **Example Scenarios:**
   ```c
   // Decode "€" (U+20AC)
   const uint8_t euro[] = {0xE2, 0x82, 0xAC};
   utf8_to_utf32(euro, 3, &cp, &bytes); // cp = 0x20AC, bytes = 3

   // Encode U+1F600 (😀)
   utf32_to_utf8(0x1F600, buf, sizeof(buf), &written); // 4 bytes
   ```

This implementation prioritizes safety and correctness while being efficient for single-codepoint conversions. For high-throughput scenarios, you might want to optimize for batch processing.

