```c
#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>

/**
 * Reads a little-endian uint64 and a varint from a byte buffer with bounds checking.
 * 
 * @param buffer     Pointer to the input byte buffer
 * @param buffer_len Total length of the buffer
 * @param cursor     Pointer to the current position (will be advanced)
 * @param out_u64    Output location for the uint64 value
 * @param out_varint Output location for the varint value
 * @return true if successful, false if buffer underflow or invalid varint
 */
bool read_le64_and_varint(
    const uint8_t *buffer, 
    size_t buffer_len, 
    size_t *cursor, 
    uint64_t *out_u64,
    uint64_t *out_varint
) {
    // Safety checks
    if (!buffer || !cursor || !out_u64 || !out_varint) {
        return false;
    }

    // Ensure we have at least 8 bytes for the uint64
    if (*cursor + 8 > buffer_len) {
        return false;
    }

    // Read little-endian uint64 (8 bytes)
    uint64_t u64 = 0;
    for (int i = 0; i < 8; i++) {
        u64 |= ((uint64_t)buffer[*cursor + i]) << (i * 8);
    }
    *cursor += 8;
    *out_u64 = u64;

    // Read varint (variable-length integer)
    uint64_t varint = 0;
    int shift = 0;
    uint8_t byte;
    const int max_varint_bytes = 10; // For 64-bit integers

    for (int i = 0; i < max_varint_bytes; i++) {
        // Check bounds
        if (*cursor >= buffer_len) {
            return false; // Buffer underflow
        }

        byte = buffer[(*cursor)++];

        // Extract 7-bit value (lower 7 bits)
        varint |= ((uint64_t)(byte & 0x7F)) << shift;

        // Check if continuation bit is set (MSB)
        if ((byte & 0x80) == 0) {
            // No more bytes needed
            *out_varint = varint;
            return true;
        }

        shift += 7;

        // Check for overflow (shift would exceed 63 bits)
        if (shift > 63) {
            return false; // Invalid varint (too long)
        }
    }

    // If we reach here, varint is malformed (no terminating byte)
    return false;
}
```

## Usage Example:

```c
#include <stdio.h>
#include <string.h>

int main() {
    // Example buffer with known values
    uint8_t buffer[20];
    size_t cursor = 0;

    // Manually encode a little-endian uint64 (0x123456789ABCDEF0)
    uint64_t test_u64 = 0x123456789ABCDEF0ULL;
    for (int i = 0; i < 8; i++) {
        buffer[i] = (test_u64 >> (i * 8)) & 0xFF;
    }

    // Encode a varint (e.g., 300 = 0x12C)
    // 300 in varint: 0xAC 0x02
    buffer[8] = 0xAC;  // 10101100 (continuation bit set)
    buffer[9] = 0x02;  // 00000010 (continuation bit clear)

    uint64_t u64, varint;
    bool success = read_le64_and_varint(buffer, 20, &cursor, &u64, &varint);

    if (success) {
        printf("Read successfully!\n");
        printf("  uint64:  0x%016llX\n", (unsigned long long)u64);
        printf("  varint:  %llu (0x%llX)\n", (unsigned long long)varint, (unsigned long long)varint);
        printf("  cursor:  %zu\n", cursor);
    } else {
        printf("Failed to read values\n");
    }

    // Test bounds checking
    uint8_t small_buffer[5] = {0, 0, 0, 0, 0};
    cursor = 0;
    success = read_le64_and_varint(small_buffer, 5, &cursor, &u64, &varint);
    if (!success) {
        printf("Bounds check correctly caught insufficient data\n");
    }

    return 0;
}
```

## Key Features:

1. **Bounds Checking**: Every read operation checks against buffer limits
2. **Little-Endian uint64**: Reads bytes in LSB-first order
3. **Varint Support**: Handles variable-length integers with continuation bits (Protocol Buffers style)
4. **Error Handling**: Returns `false` for buffer underflows, invalid varints, or null pointers
5. **Max Length Validation**: Limits varint to 10 bytes (for 64-bit integers)
6. **Cursor Advancement**: Properly advances the cursor for both reads

## Varint Encoding Explained:
- Each byte uses 7 bits for data + 1 continuation bit (MSB)
- If MSB is 1, another byte follows
- If MSB is 0, this is the last byte
- Example: 300 = `0x12C` = `0xAC 0x02` (10101100 00000010)

The function handles the common edge cases like null pointers, buffer overflow, and malformed varints that could otherwise cause security issues.

```c
/* json_tok.c — Minimal JSON tokenizer, no dependencies.
 * Compile: gcc -O2 -o json_tok json_tok.c
 * Usage:   ./json_tok '{"key": [1, true, null, "hello"]}'
 */

#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

/* ── token types ─────────────────────────────────────────────── */
typedef enum {
    TOK_LBRACE,   /* {   */
    TOK_RBRACE,   /* }   */
    TOK_LBRACKET, /* [   */
    TOK_RBRACKET, /* ]   */
    TOK_COLON,    /* :   */
    TOK_COMMA,    /* ,   */
    TOK_STRING,
    TOK_NUMBER,
    TOK_TRUE,
    TOK_FALSE,
    TOK_NULL,
    TOK_EOF,
    TOK_ERROR
} TokType;

static const char *tok_names[] = {
    "LBRACE", "RBRACE", "LBRACKET", "RBRACKET",
    "COLON", "COMMA", "STRING", "NUMBER",
    "TRUE", "FALSE", "NULL", "EOF", "ERROR"
};

/* ── token struct ────────────────────────────────────────────── */
typedef struct {
    TokType type;
    size_t  start;   /* offset into source string */
    size_t  length;  /* number of source chars consumed */
} Token;

/* ── tokenizer state ─────────────────────────────────────────── */
typedef struct {
    const char *src;
    size_t      len;
    size_t      pos;
} TokState;

/* ── helpers ─────────────────────────────────────────────────── */
static int peek(TokState *s) {
    return s->pos < s->len ? (unsigned char)s->src[s->pos] : EOF;
}

static int advance(TokState *s) {
    return s->pos < s->len ? (unsigned char)s->src[s->pos++] : EOF;
}

static void skip_whitespace(TokState *s) {
    while (s->pos < s->len) {
        int c = (unsigned char)s->src[s->pos];
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r')
            s->pos++;
        else
            break;
    }
}

static Token make_token(TokType type, size_t start, size_t length) {
    Token t;
    t.type   = type;
    t.start  = start;
    t.length = length;
    return t;
}

/* ── string tokenizer (handles escapes) ──────────────────────── */
static Token tokenize_string(TokState *s) {
    size_t start = s->pos - 1; /* include opening quote */
    int c;
    while ((c = advance(s)) != EOF) {
        if (c == '"')
            return make_token(TOK_STRING, start, s->pos - start);
        if (c == '\\') {
            if (advance(s) == EOF)  /* skip escaped char */
                break;
        }
    }
    return make_token(TOK_ERROR, start, s->pos - start);
}

/* ── number tokenizer ────────────────────────────────────────── */
static Token tokenize_number(TokState *s) {
    size_t start = s->pos - 1;
    int c = peek(s);

    /* optional minus */
    if (c == '-') c = advance(s);

    /* integer part */
    if (c == '0') {
        c = advance(s);
    } else if (c >= '1' && c <= '9') {
        while ((c = peek(s)) >= '0' && c <= '9') advance(s);
    } else {
        return make_token(TOK_ERROR, start, s->pos - start);
    }

    /* fraction */
    if (peek(s) == '.') {
        advance(s);
        c = peek(s);
        if (c < '0' || c > '9')
            return make_token(TOK_ERROR, start, s->pos - start);
        while ((c = peek(s)) >= '0' && c <= '9') advance(s);
    }

    /* exponent */
    c = peek(s);
    if (c == 'e' || c == 'E') {
        advance(s);
        c = peek(s);
        if (c == '+' || c == '-') advance(s);
        c = peek(s);
        if (c < '0' || c > '9')
            return make_token(TOK_ERROR, start, s->pos - start);
        while ((c = peek(s)) >= '0' && c <= '9') advance(s);
    }

    return make_token(TOK_NUMBER, start, s->pos - start);
}

/* ── keyword tokenizer ───────────────────────────────────────── */
static Token tokenize_keyword(TokState *s, const char *kw, TokType type) {
    size_t kw_len = strlen(kw);
    size_t start  = s->pos - 1;

    if (s->pos + kw_len - 1 > s->len ||
        memcmp(s->src + start, kw, kw_len) != 0)
        return make_token(TOK_ERROR, start, s->pos - start);

    s->pos += kw_len - 1;  /* first char already consumed */
    return make_token(type, start, kw_len);
}

/* ── main tokenizer ──────────────────────────────────────────── */
static size_t tokenize(const char *json, size_t len, Token **out) {
    TokState s = { json, len, 0 };

    /* worst case: every char is a separate token + 1 EOF */
    size_t cap = len + 1;
    Token *tokens = malloc(cap * sizeof *tokens);
    size_t count = 0;

    for (;;) {
        skip_whitespace(&s);
        int c = peek(&s);

        if (c == EOF) {
            tokens[count++] = make_token(TOK_EOF, s.pos, 0);
            break;
        }

        Token t;
        size_t start = s.pos;

        switch (c) {
        case '{': advance(&s); t = make_token(TOK_LBRACE,   start, 1); break;
        case '}': advance(&s); t = make_token(TOK_RBRACE,   start, 1); break;
        case '[': advance(&s); t = make_token(TOK_LBRACKET, start, 1); break;
        case ']': advance(&s); t = make_token(TOK_RBRACKET, start, 1); break;
        case ':': advance(&s); t = make_token(TOK_COLON,    start, 1); break;
        case ',': advance(&s); t = make_token(TOK_COMMA,    start, 1); break;
        case '"':
            advance(&s);
            t = tokenize_string(&s);
            break;
        case 't': advance(&s); t = tokenize_keyword(&s, "rue",  TOK_TRUE);  break;
        case 'f': advance(&s); t = tokenize_keyword(&s, "alse", TOK_FALSE); break;
        case 'n': advance(&s); t = tokenize_keyword(&s, "ull",  TOK_NULL);  break;
        default:
            if (c == '-' || (c >= '0' && c <= '9')) {
                advance(&s);
                t = tokenize_number(&s);
            } else {
                advance(&s);
                t = make_token(TOK_ERROR, start, 1);
            }
            break;
        }

        tokens[count++] = t;
    }

    *out = tokens;
    return count;
}

/* ── demo ────────────────────────────────────────────────────── */
int main(int argc, char **argv) {
    const char *json = argc > 1 ? argv[1]
        : "{\"name\": \"Alice\", \"age\": 30, "
          "\"scores\": [99.5, -7, 0, 1e2], "
          "\"active\": true, \"note\": null}";

    size_t len  = strlen(json);
    Token *tokens = NULL;
    size_t count  = tokenize(json, len, &tokens);

    printf("Source (%zu chars): %s\n\n", len, json);
    printf("%-12s  %-6s  %-6s  Content\n", "Type", "Start", "Len");
    printf("----------------------------------------\n");

    for (size_t i = 0; i < count; i++) {
        Token *t = &tokens[i];
        printf("%-12s  %4zu    %4zu    \"",
               tok_names[t->type], t->start, t->length);

        /* print the matched source text (quotes included for strings) */
        for (size_t j = 0; j < t->length; j++) {
            int ch = (unsigned char)json[t->start + j];
            if (ch == '\\')
                printf("\\\\");
            else if (ch == '"')
                printf("\\\"");
            else if (ch < 0x20)
                printf("\\x%02x", ch);
            else
                putchar(ch);
        }
        printf("\"\n");
    }

    free(tokens);
    return 0;
}
```



